INSERT INTO changelog (title, body, created_at) VALUES ('Оновлення продукту: 1, 2, 3…', 'Після першого повного паспорта на сторінці продукту зʼявляється головна кнопка «Промпт: оновлення N». У промпті — на чому ми зупинились (останнє оновлення, останні етапи, відкриті кроки, наступний крок). Claude Code віддає тільки нове блоком [CLIENT-OPS:ОНОВЛЕННЯ] — вставляєш у «Вставити витяжку» або кидаєш Джері.
Кожне оновлення отримує номер (Оновлення 1, 2, 3…): етапи лягають у хронологію з позначкою номера, знання/рішення/кроки — теж. На паспорті зверху — «Де зупинились» (з останнього оновлення) і список усіх оновлень (клік — подробиці). «Повний промпт» лишився — для великої роботи з усім паспортом.', datetime('now'));
